INSERT INTO "Level" ("id", "gdLevelId", "name", "mode", "difficulty", "difficultyFace", "ratingType", "isVN", "isChallenge", "placement", "vnPlacement", "basePp", "minPercent", "creatorName", "creatorId", "verifierName", "youtubeId", "description", "createdAt", "updatedAt") VALUES ('f77c25ec-66e7-40eb-acb2-3987f49c6279', 125486820, 'Carmine Cascade', 'CLASSIC', 'Extreme Demon', 14, 'NONE', FALSE, FALSE, 696, NULL, 10, 100, 'AAAAAlex', NULL, NULL, NULL, 'Scarlet Surge remake with the signature deep red flashy pulses. Features much more memory heavy gameplay than the original, in AAAAAlex''s signature style. Extremely well received despite technically being a superbuffed 7 star.', '2026-08-30T09:04:55.849Z', '2026-09-06T06:19:25.140Z') ON CONFLICT DO NOTHING;
INSERT INTO "Level" ("id", "gdLevelId", "name", "mode", "difficulty", "difficultyFace", "ratingType", "isVN", "isChallenge", "placement", "vnPlacement", "basePp", "minPercent", "creatorName", "creatorId", "verifierName", "youtubeId", "description", "createdAt", "updatedAt") VALUES ('d676f7d8-59b3-4e7e-bf3e-66ba23b59b13', 110769422, 'Magnificent Gaps', 'CLASSIC', 'Extreme Demon', 14, 'NONE', FALSE, FALSE, 602, NULL, 10, 100, NULL, NULL, NULL, NULL, 'A magnificent remake of Impossible Gaps with a lot of finicky gimmicks and a short 2 player part. The level is fully ship gamemode with simple cute designs and visuals. The lord of chokepoints and raw skill gameplay, johnnwaogus magnificent masterpiece', '2026-08-30T08:27:36.111Z', '2026-09-06T06:19:25.140Z') ON CONFLICT DO NOTHING;
