INSERT INTO "Level" ("id", "gdLevelId", "name", "mode", "difficulty", "difficultyFace", "ratingType", "isVN", "isChallenge", "placement", "vnPlacement", "basePp", "minPercent", "creatorName", "creatorId", "verifierName", "youtubeId", "description", "createdAt", "updatedAt") VALUES ('150274ce-cb7b-4e91-9428-b5ae89722fbb', 58578389, 'Khorne', 'CLASSIC', 'Demon', 0, 'NONE', FALSE, FALSE, 692, NULL, 10, 100, NULL, NULL, NULL, NULL, 'Legendary extreme demon with a very rich history. The original version created by Hota1991 had around a million objects, the most out of any level of its time. Because of how laggy the level was for most people, Stilluetto created an nerfed optimized version, cutting the object count in half. The original version was rated twice on accident, once in 2023 and again in 2026 right before the optimized version got rated. The level is split into nine parts, each exploring a different part of hell.', '2026-08-30T09:04:55.700Z', '2026-09-06T06:19:25.140Z') ON CONFLICT DO NOTHING;
