INSERT INTO "Level" ("id", "gdLevelId", "name", "mode", "difficulty", "difficultyFace", "ratingType", "isVN", "isChallenge", "placement", "vnPlacement", "basePp", "minPercent", "creatorName", "creatorId", "verifierName", "youtubeId", "description", "createdAt", "updatedAt") VALUES ('884e3bae-1691-44fe-b2d9-bd6b23af9086', 106362836, 'Alpha', 'CLASSIC', 'Demon', 0, 'NONE', FALSE, FALSE, 321, NULL, 72.47, 100, NULL, NULL, NULL, NULL, 'A traditional-styled level which has faced over 6 years of on-and-off building and countless buffs, nerfs and rebalances. Despite everything it went through it managed to become highly enjoyed amongst its victors. Very timing-based with the main highlight being the 39% dual, though it has several short bursts of more skill-based gameplay throughout.', '2026-08-30T05:56:15.095Z', '2026-09-06T06:19:25.140Z') ON CONFLICT DO NOTHING;
INSERT INTO "Level" ("id", "gdLevelId", "name", "mode", "difficulty", "difficultyFace", "ratingType", "isVN", "isChallenge", "placement", "vnPlacement", "basePp", "minPercent", "creatorName", "creatorId", "verifierName", "youtubeId", "description", "createdAt", "updatedAt") VALUES ('1d224194-5001-4a12-9864-25df1f149963', 133286402, 'Retention Redux', 'CLASSIC', 'Demon', 0, 'NONE', FALSE, FALSE, 324, NULL, 70.11, 100, NULL, NULL, NULL, NULL, 'Faithful retention remake passion project aimed to capture the essence of the original. Inspired from the creator''s experience beating Retention as a first extreme. Gameplay takes light inspiration from the original while being very well-received, and the decoration boosts the object density and vibrancy. Built entirely on mobile!', '2026-08-30T05:56:15.209Z', '2026-09-06T06:19:25.140Z') ON CONFLICT DO NOTHING;
INSERT INTO "Level" ("id", "gdLevelId", "name", "mode", "difficulty", "difficultyFace", "ratingType", "isVN", "isChallenge", "placement", "vnPlacement", "basePp", "minPercent", "creatorName", "creatorId", "verifierName", "youtubeId", "description", "createdAt", "updatedAt") VALUES ('a035cbdb-13d5-4f75-8e30-ce0b465e4c18', 112998648, 'Piano Woman', 'CLASSIC', 'Demon', 0, 'NONE', FALSE, FALSE, 327, NULL, 67.82, 100, NULL, NULL, NULL, NULL, 'The sequel to Piano Man. A true solo, with pukklez making the song, the level, and being the verifier. Every input is 2.5 frames on 60fps.', '2026-08-30T05:56:15.321Z', '2026-09-06T06:19:25.140Z') ON CONFLICT DO NOTHING;
