INSERT INTO "HelpRequest" ("id", "userId", "title", "content", "status", "reviewNote", "createdAt") VALUES ('cmtq28mop0001jr0463fvakc9', '7d69f7e7-938d-43b9-bc61-e38786e61770', 'đơn yêu cầu lấy lại record cũ và đồng nhất với tài khoản cũ làm một', 'Xin lỗi nhưng mà tôi đã có 1 tài khoản với 3 record là "Bloodbath" "Cataclysm" và "Tung Tung Sahurcles" với Username là NotelpmaoGMD, User GD là notenvngd25,có lẽ do acc GDVN cũ tôi viết hoa chữ N đầu của User GD nên kiểm duyệt viên hoặc bot không tìm được, kênh YT là @notelpmaovien252, rất xin lỗi chân thành về sai lầm ngớ ngẩn này của tôi. nếu sau này thực sự cần phải chứng minh 3 record cũ này thì tôi sẽ cố up thêm record tại web gdvn mới này với góc handcam,kênh,icon đồng nhất để không gây nghi vấn cho kiểm duyệt viên và đóng góp thêm cho GDVN.thanks;)', 'APPROVED', 'ok tui lay lai dc r', '2026-09-06T17:03:00.313Z') ON CONFLICT DO NOTHING;
INSERT INTO "HelpRequest" ("id", "userId", "title", "content", "status", "reviewNote", "createdAt") VALUES ('cmtq38qfk0001js04i6m4cgzr', '0fd84b50-7744-400a-8e45-acd905c3f417', 'Record cũ', 'Xin chào Mod/Admin. Ở web gdvn.net cũ mình có 1 record đã nộp nhưng chưa được xác minh về killbot. Thì Mod/Admin có thể để ngày beat đúng với lúc mình nộp được không ạ, ngay sau khi mình nộp', 'APPROVED', NULL, '2026-09-06T17:31:04.784Z') ON CONFLICT DO NOTHING;
INSERT INTO "HelpRequest" ("id", "userId", "title", "content", "status", "reviewNote", "createdAt") VALUES ('cmtqdxoks0001l7041r96pj5c', '2ad8689b-8577-45cd-a7f6-3a38466f93ea', 'Progress có bị mất không ạ', 'Chuyền là ở web cũ gdvn.net mình có nộp submit màn extreme demon Without U, tới giờ vẫn chưa duyệt xong mà web đó nghe có người trong server discord nói là đã bán sạch data web rồi, mình chỉ muốn hỗ trợ lấy lại bản submit đó vì mình đăng vào 2/9 đúng sinh nhật mình mà giờ như vậy khá là tiếc nếu phải nộp lại từ bây giờ ấy, mong đội ngũ hỗ trợ giúp mình và nhân tiện có thể kiểm tra submit luôn ạ
