INSERT INTO "SiteAnnouncement" ("id", "title", "excerpt", "body", "audience", "targetUserIds", "authorId", "createdAt", "updatedAt") VALUES ('18f55948-6800-487b-8a2e-48a374b67a3d', 'Thông báo: về việc lấy lại record cũ', 'GD username của bạn phải giống với tên tài khoản web cũ', 'Để lấy lại record cũ từ web trước đó (đúng hơn là được nhập lại từ web đó sang đây), bạn cần phải đặt GD username của bản thân (trong trang profile có cái GD username sửa được á) sao cho giống với tên tài khoản trên web cũ hoặc tên chưa có tài khoản đang hiển thị trong bảng xếp hạng. Sau đó vào phần hỗ trợ và gửi yêu cầu xác minh tài khoản cho mình, bạn có thể sửa gd username sau đó duyệt lại sau này cũng được.', 'ALL', '{}', '906cc15d-3ca2-4858-932b-b8d85f899e08', '2026-08-30T04:09:14.512Z', '2026-08-30T04:09:14.512Z') ON CONFLICT DO NOTHING;
